'use client';
import React from 'react';

import { Categories, SkinTonePickerLocation } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// In context: a project settings form. Picking an emoji sets the
// project's icon (live preview tile); categories are narrowed to the ones
// that make sense as icons.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  const [icon, setIcon] = React.useState('🚀');
  return (
    <form className="project-card" onSubmit={(event) => event.preventDefault()}>
      <h2 className="project-heading">Project settings</h2>
      <div className="project-row">
        <span className="project-tile" aria-label={`Project icon ${icon}`} role="img">
          {icon}
        </span>
        <div className="project-name">
          <span className="project-field-label">Name</span>
          <span className="project-field">Website redesign</span>
        </div>
      </div>
      <p className="project-field-label">Icon</p>
      <RootComponent appearance="default"
        className={className}
        searchPlaceholder="Search icons"
        skinTonePickerLocation={SkinTonePickerLocation.NONE}
        autoFocusSearch={false}
        onEmojiClick={(emoji: { emoji: string }) => setIcon(emoji.emoji)}
        categories={[
          Categories.OBJECTS,
          Categories.ACTIVITIES,
          Categories.TRAVEL_PLACES,
          Categories.ANIMALS_NATURE,
          Categories.FOOD_DRINK,
          Categories.SYMBOLS,
        ]}
      >
        <div className="project-toolbar">
          <Picker.Search />
          <Picker.CategoryNav />
        </div>
        <Picker.Viewport>
          <Picker.List />
          <Picker.Empty />
        </Picker.Viewport>
      </RootComponent>
    </form>
  );
}

/* The host app around the picker (shared by every stack variant). */
.project-card {
  width: 560px;
  padding: 24px;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  background: #ffffff;
  color: #111827;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.project-heading {
  margin: 0 0 18px;
  font-size: 18px;
}
.project-row {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 18px;
}
.project-tile {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  border-radius: 16px;
  background: linear-gradient(135deg, #fef3c7, #fde68a);
  font-size: 34px;
}
.project-name {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 6px;
}
.project-field-label {
  margin: 0 0 6px;
  color: #374151;
  font-size: 13px;
  font-weight: 600;
}
.project-field {
  padding: 9px 12px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font-size: 14px;
}

/* Project icon picker — an inline form control: search and tabs share one
   toolbar row, an evenly gridded well below. */
.project-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #d97706;
  --epr-hover-bg-color: #fef3c7;
  --epr-focus-bg-color: #fde68a;
  --epr-search-input-bg-color: #f9fafb;
  --epr-search-input-bg-color-active: #ffffff;
  --epr-search-border-color: #d1d5db;
  --epr-search-border-color-active: #d97706;
  --epr-search-input-height: 34px;
  --epr-search-input-border-radius: 8px;
  --epr-search-input-text-color: #111827;
  --epr-search-input-placeholder-color: #6b7280;
  --epr-category-label-bg-color: #fffffff2;
  --epr-category-label-text-color: #4b5563;
  --epr-category-label-height: 28px;
  --epr-category-icon-active-color: #b45309;
  --epr-category-icon-inactive-color: #6b7280;
  --epr-category-navigation-button-size: 20px;
  --epr-emoji-size: 26px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 10px;
  height: 260px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  background: #ffffff;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.project-picker .project-toolbar {
  display: flex;
  align-items: center;
  border-bottom: 1px solid #f3f4f6;
}
.project-picker [data-epr-part='search'] {
  flex: 1;
}
.project-picker [data-epr-part='search'] > * {
  padding: 10px 6px 10px 10px;
}
.project-picker [data-epr-part='category-nav'] > * {
  gap: 6px;
  padding: 0 10px 0 4px;
}
.project-picker [data-epr-part='category-tab'][aria-selected='true'] {
  border-radius: 6px;
  background-color: #fef3c7;
}
.project-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
}
.project-picker [data-epr-part='emoji'] {
  border-radius: 10px;
}

